"use no memo";
import React from 'react';
import {
  FlexWidget,
  ImageWidget,
  TextWidget,
} from 'react-native-android-widget';
import type { ColorProp } from 'react-native-android-widget';

import type { WidgetData } from './data';

const NAVBAR: ColorProp   = '#121212';
const CARD: ColorProp     = '#202020';
const TEXT: ColorProp     = '#FFFFFF';
const MUTED: ColorProp    = '#9E9E9E';
const PRIMARY: ColorProp  = '#FFC107';
const ACCENT_BG           = '#1A2A00' as ColorProp;

const IMG_HOME      = 'data:image/png;base64,';
const IMG_GAS       = 'data:image/png;base64,';
const IMG_NAV       = 'data:image/png;base64,';
const IMG_ADD       = 'data:image/png;base64,';
const IMG_PLAY      = 'data:image/png;base64,';
const IMG_PAUSE     = 'data:image/png;base64,';
const IMG_STOP      = 'data:image/png;base64,';
const IMG_COFFEE    = 'data:image/png;base64,';
const IMG_CIGARETTE = 'data:image/png;base64,';

export interface AllInOneWidgetProps extends WidgetData {
  shortcuts: { name: string; lat: number | null; lng: number | null }[];
  tripStatus?: 'idle' | 'active' | 'paused';
  spinAngle?: number;
}

/** Bouton icône — tous identiques en flex:1 et hauteur match_parent */
function ImgBtn({
  image,
  clickAction,
  bg = CARD,
}: {
  image: string;
  clickAction: string;
  bg?: ColorProp;
}) {
  return (
    <FlexWidget
      clickAction={clickAction}
      style={{
        flex: 1,
        height: 'match_parent',
        justifyContent: 'center',
        alignItems: 'center',
        backgroundColor: bg,
        borderRadius: 8,
      }}
    >
      <ImageWidget
        image={image as any}
        imageWidth={24}
        imageHeight={24}
        style={{ width: 24, height: 24 }}
      />
    </FlexWidget>
  );
}

export function AllInOneWidget({
  tasks,
  widgetAppts,
  todayWork,
  todayDayNum,
  marieCircleColor,
  tripStatus = 'idle',
}: AllInOneWidgetProps) {
  const isRepos  = todayWork === 'Repos';
  const nextAppt = widgetAppts[0] ?? null;

  return (
    <FlexWidget
      clickAction="OPEN_APP"
      style={{
        height: 'match_parent',
        width: 'match_parent',
        backgroundColor: NAVBAR,
        borderRadius: 14,
        paddingHorizontal: 8,
        paddingTop: 4,
        paddingBottom: 4,
        flexDirection: 'column',
        flexGap: 3,
      }}
    >
      {/* ─── Ligne 1 : infos ─── */}
      <FlexWidget
        style={{
          width: 'match_parent',
          flexDirection: 'row',
          alignItems: 'center',
          height: 22,
          flexGap: 7,
        }}
      >
        {/* Anneau refresh coloré = couleur shift Marie */}
        <FlexWidget
          clickAction="REFRESH"
          style={{
            width: 32,
            height: 32,
            borderRadius: 16,
            backgroundColor: marieCircleColor as ColorProp,
            alignItems: 'center',
            justifyContent: 'center',
          }}
        >
          {/* Cercle intérieur sombre = effet anneau */}
          <FlexWidget
            style={{
              width: 25,
              height: 25,
              borderRadius: 13,
              backgroundColor: NAVBAR,
              alignItems: 'center',
              justifyContent: 'center',
            }}
          >
            <TextWidget
              text={String(todayDayNum)}
              style={{ fontSize: 11, fontWeight: 'bold', color: '#FFFFFF' }}
            />
          </FlexWidget>
        </FlexWidget>

        {/* Travail */}
        <TextWidget
          text={isRepos ? 'Repos' : todayWork}
          style={{ fontSize: 11, color: isRepos ? MUTED : PRIMARY, fontWeight: 'bold' }}
          maxLines={1}
          truncate="END"
        />

        {/* Spacer */}
        <FlexWidget style={{ flex: 1, height: 1, backgroundColor: NAVBAR }} />

        {/* Tasks */}
        <TextWidget
          text={`${tasks.length} taches`}
          style={{ fontSize: 10, color: TEXT }}
        />

        {/* Appt */}
        {nextAppt ? (
          <TextWidget
            text={`· ${nextAppt.title}`}
            style={{ fontSize: 10, color: PRIMARY }}
            maxLines={1}
            truncate="END"
          />
        ) : null}
      </FlexWidget>

      {/* ─── Ligne 2 : 7 boutons + gap ─── */}
      <FlexWidget
        style={{
          flexDirection: 'row',
          width: 'match_parent',
          height: 38,
          alignItems: 'center',
          flexGap: 4,
        }}
      >
        {/* Groupe gauche : Maison · Essence · Nav · Transaction · Play */}
        <ImgBtn image={IMG_HOME} clickAction="NAVIGATE_HOME" />
        <ImgBtn image={IMG_GAS}  clickAction="OPEN_FUEL" />
        <ImgBtn image={IMG_NAV}  clickAction="NAVIGATE_TO" />
        <ImgBtn image={IMG_ADD}  clickAction="ADD_TRANSACTION" />

        {tripStatus === 'idle' && (
          <ImgBtn image={IMG_PLAY}  clickAction="MANUAL_TRIP_START" bg={ACCENT_BG} />
        )}
        {tripStatus === 'active' && (
          <ImgBtn image={IMG_PAUSE} clickAction="MANUAL_TRIP_PAUSE" />
        )}
        {tripStatus === 'active' && (
          <ImgBtn image={IMG_STOP}  clickAction="MANUAL_TRIP_END" />
        )}
        {tripStatus === 'paused' && (
          <ImgBtn image={IMG_PLAY}  clickAction="MANUAL_TRIP_RESUME" bg={ACCENT_BG} />
        )}
        {tripStatus === 'paused' && (
          <ImgBtn image={IMG_STOP}  clickAction="MANUAL_TRIP_END" />
        )}

        {/* Séparateur visuel entre Play et Café */}
        <FlexWidget
          style={{
            width: 10,
            height: 'match_parent',
            backgroundColor: NAVBAR,
          }}
        />

        {/* Groupe droit : Café · Clope */}
        <ImgBtn image={IMG_COFFEE}    clickAction="ADD_COFFEE" />
        <ImgBtn image={IMG_CIGARETTE} clickAction="ADD_CIGARETTE" />
      </FlexWidget>
    </FlexWidget>
  );
}
